insert into homepage_sections (section_key, enabled, sort_order, content) values
  ('HERO', true, 0, $j$ {"fr": {"title": "La géographie au service du territoire et du développement durable", "description": "L'ANAGEM fédère les géographes marocains, produit et diffuse le savoir géographique, et contribue à l'éclairage des territoires et des politiques publiques.", "primaryCta": "Découvrir l'association", "secondaryCta": "Voir nos publications", "sideText": "Comprendre les territoires pour construire demain"}, "ar": {"title": "الجغرافيا في خدمة المجال والتنمية المستدامة", "description": "تجمع الجمعية الوطنية للجغرافيين المغاربة الجغرافيين المغاربة، وتنتج المعرفة الجغرافية وتنشرها، وتسهم في فهم المجالات والسياسات العمومية.", "primaryCta": "اكتشف الجمعية", "secondaryCta": "اطّلع على منشوراتنا", "sideText": "فهم المجالات لبناء الغد"}, "en": {"title": "Geography serving territories and sustainable development", "description": "ANAGEM brings Moroccan geographers together, produces and shares geographical knowledge, and helps illuminate territories and public policy.", "primaryCta": "Discover the association", "secondaryCta": "See our publications", "sideText": "Understanding territories to build tomorrow"}, "common": {"primaryUrl": "/association", "secondaryUrl": "/publications", "heroImageMediaId": null, "sideImageMediaId": null}} $j$::jsonb),
  ('QUICK_ACCESS', true, 10, $j$ {"items": [{"key": "association", "icon": "users", "url": "/association", "fr": {"title": "L'association", "description": "Historique, statuts, instances"}, "ar": {"title": "الجمعية", "description": "التاريخ، القانون الأساسي، الهياكل"}, "en": {"title": "Association", "description": "History, statutes, bodies"}}, {"key": "publications", "icon": "book-open", "url": "/publications", "fr": {"title": "Publications", "description": "Revue, ouvrages, actes"}, "ar": {"title": "المنشورات", "description": "المجلة، الكتب، أعمال الملتقيات"}, "en": {"title": "Publications", "description": "Journal, books, proceedings"}}, {"key": "events", "icon": "calendar-days", "url": "/events", "fr": {"title": "Colloques & Événements", "description": "Actualités, inscriptions"}, "ar": {"title": "الندوات والتظاهرات", "description": "الأخبار والتسجيل"}, "en": {"title": "Conferences & Events", "description": "News, registration"}}, {"key": "members", "icon": "users", "url": "/members", "fr": {"title": "Membres", "description": "Annuaire, adhésion"}, "ar": {"title": "الأعضاء", "description": "الدليل والانخراط"}, "en": {"title": "Members", "description": "Directory, membership"}}, {"key": "resources", "icon": "file-text", "url": "/resources", "fr": {"title": "Ressources", "description": "Documents, liens utiles"}, "ar": {"title": "الموارد", "description": "وثائق وروابط مفيدة"}, "en": {"title": "Resources", "description": "Documents, useful links"}}, {"key": "contact", "icon": "mail", "url": "/contact", "fr": {"title": "Contact", "description": "Nous écrire"}, "ar": {"title": "اتصل بنا", "description": "راسلونا"}, "en": {"title": "Contact", "description": "Write to us"}}]} $j$::jsonb),
  ('THEMATIC_AREAS', true, 20, $j$ {"title": {"fr": "Axes thématiques", "ar": "المحاور", "en": "Thematic areas"}, "items": [{"key": "natural-environments", "icon": "leaf", "fr": {"title": "Environnements naturels"}, "ar": {"title": "الأوساط الطبيعية"}, "en": {"title": "Natural environments"}}, {"key": "territorial-inequalities", "icon": "scale", "fr": {"title": "Inégalités territoriales"}, "ar": {"title": "التفاوتات المجالية"}, "en": {"title": "Territorial inequalities"}}, {"key": "governance", "icon": "landmark", "fr": {"title": "Gouvernance"}, "ar": {"title": "الحكامة"}, "en": {"title": "Governance"}}, {"key": "innovation", "icon": "lightbulb", "fr": {"title": "Innovation"}, "ar": {"title": "الابتكار"}, "en": {"title": "Innovation"}}]} $j$::jsonb),
  ('MEMBERSHIP_CARDS', true, 30, $j$ {"items": [{"key": "about", "icon": "users", "url": "/association", "fr": {"title": "À propos de l'ANAGEM", "text": "L'ANAGEM rassemble les géographes marocains et toutes celles et ceux qui s'intéressent à la géographie. Elle diffuse l'information sur la géographie du Maroc et organise conférences, séminaires, journées d'étude, voyages et expositions.", "cta": "Découvrir l'association"}, "ar": {"title": "حول الجمعية", "text": "تضم الجمعية الجغرافيين المغاربة وكل المهتمين بالجغرافيا، وتعمل على جمع وتعميم المعلومات المتعلقة بجغرافية المغرب، وتنظم محاضرات وندوات وأيامًا دراسية ورحلات ومعارض.", "cta": "اكتشف الجمعية"}, "en": {"title": "About ANAGEM", "text": "ANAGEM brings together Moroccan geographers and everyone interested in geography. It shares information on the geography of Morocco and organises lectures, seminars, study days, field trips and exhibitions.", "cta": "Discover the association"}}, {"key": "join", "icon": "user-plus", "url": "/members/join", "fr": {"title": "Adhésion", "text": "Rejoignez notre réseau et participez à la dynamique scientifique de l'ANAGEM. Les statuts prévoient plusieurs catégories de membres : actifs, correspondants, d'honneur et étudiants.", "cta": "Adhérer en ligne"}, "ar": {"title": "الانخراط", "text": "انضموا إلى شبكتنا وشاركوا في الدينامية العلمية للجمعية. ينص القانون الأساسي على عدة فئات من الأعضاء: النشيطون والمراسلون وأعضاء الشرف والطلبة.", "cta": "انخرط عبر الإنترنت"}, "en": {"title": "Membership", "text": "Join our network and take part in ANAGEM's scientific community. The statutes provide for several member categories: active, corresponding, honorary and student.", "cta": "Join online"}}, {"key": "space", "icon": "lock", "url": "/members/login", "fr": {"title": "Espace membres", "text": "Accédez à votre espace personnel pour gérer votre profil, consulter les ressources et suivre les actualités.", "cta": "Se connecter"}, "ar": {"title": "فضاء الأعضاء", "text": "ادخلوا إلى فضائكم الشخصي لتدبير ملفكم والاطلاع على الموارد ومتابعة المستجدات.", "cta": "تسجيل الدخول"}, "en": {"title": "Members' area", "text": "Access your personal space to manage your profile, browse resources and follow the news.", "cta": "Sign in"}}]} $j$::jsonb),
  ('FEATURED_EVENT', true, 40, $j$ {"mode": "AUTO", "eventId": null} $j$::jsonb),
  ('MAGAZINE', true, 50, $j$ {"mode": "AUTO", "publicationId": null, "kicker": {"fr": "Revue de l'ANAGEM", "ar": "مجلة الجمعية", "en": "ANAGEM journal"}} $j$::jsonb),
  ('PARTNERS', true, 60, $j$ {"title": {"fr": "Nos partenaires", "ar": "شركاؤنا", "en": "Our partners"}} $j$::jsonb),
  ('FOOTER', true, 70, $j$ {"tagline": {"fr": "Ensemble pour les territoires de demain", "ar": "معًا من أجل مجالات الغد", "en": "Together for the territories of tomorrow"}, "rights": {"fr": "© 2026 ANAGEM. Tous droits réservés.", "ar": "© 2026 الجمعية الوطنية للجغرافيين المغاربة. جميع الحقوق محفوظة.", "en": "© 2026 ANAGEM. All rights reserved."}} $j$::jsonb);
